18	     * right-to-left, doubling alternate digits (starting with the rightmost) and subtracting 9
19	     * from any doubled value over 9; the check digit makes that sum a multiple of 10.
20	     */
21	    static int of(String customerCode) {
22	        int sum = 0;
23	        boolean dbl = true;
