7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>} where CITY3 is
9	 * the upper-cased first three letters of the city, LAST3 the upper-cased first three letters of the
10	 * last name and NNNN a per-city 4-digit zero-padded sequence equal to one more than the number of
11	 * owners already in that city (e.g. {@code SYD-SMI-0007}).
12	 *
13	 * <p>Runs before {@link SaveOwner}, so the count reflects the owners already persisted in the same
14	 * city and the new owner receives the next number in that city's sequence.
15	 */
16	public class AssignCustomerCode {
17	
18	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
19	        String city3 = prefix(owner.getCity());
20	        String last3 = prefix(owner.getLastName());
21	        int sequence = countInCity(owner.getCity(), ownerRepository) + 1;
22	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
23	    }
24	
25	    /** Upper-cased first three letters of {@code value}. */
26	    private static String prefix(String value) {
27	        return value.substring(0, Math.min(3, value.length())).toUpperCase();
28	    }
29	
30	    /** Number of existing owners in {@code city}, compared case-insensitively. */
31	    private static int countInCity(String city, OwnerRepository ownerRepository) {
32	        int count = 0;
33	        for (Owner existing : ownerRepository.findAll()) {
34	            if (city == null ? existing.getCity() == null : city.equalsIgnoreCase(existing.getCity())) {
35	                count++;
36	            }
37	        }
38	        return count;
39	    }
40	}
