1	package org.springframework.samples.petclinic.mapper;
2	
3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's canonical region ('locality'). The postcode is preferred: when it falls
7	 * within a known region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
8	 * {@code QLD 4000-4099}) that region wins. Only when the postcode is absent, malformed or in no
9	 * known range does it fall back to the fixed city-to-region table. This returns the same region
10	 * for known cities but disambiguates cities that share a name.
11	 *
12	 * <p>Kept as a standalone helper (referenced from {@link OwnerMapper}'s
13	 * {@code locality} expression) rather than a mapper {@code default} method: a
14	 * {@code String}-to-{@code String} method on the mapper interface would be
15	 * picked up by MapStruct as an automatic conversion for every String property.
16	 */
17	final class Locality {
18	
19	    /** City -&gt; canonical region. Anything not listed derives {@link #UNKNOWN}. */
20	    private static final Map<String, String> CITY_REGION = Map.of(
21	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
22	
23	    /** Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. */
24	    private static final Map<String, int[]> REGION_RANGE = Map.of(
25	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
26	
27	    static final String UNKNOWN = "UNKNOWN";
28	
29	    private Locality() {
30	    }
31	
32	    /**
33	     * The canonical region for the owner, preferring the postcode. When {@code postcode} is a
34	     * 4-digit value inside a known region's range that region is returned; otherwise the
35	     * {@code city} is looked up in the city-to-region table, deriving {@code "UNKNOWN"} when it is
36	     * not listed.
37	     */
38	    static String of(String postcode, String city) {
39	        String byPostcode = byPostcode(postcode);
40	        if (byPostcode != null) {
41	            return byPostcode;
42	        }
43	        return city == null ? UNKNOWN : CITY_REGION.getOrDefault(city, UNKNOWN);
44	    }
45	
46	    /** The region whose range contains {@code postcode}, or {@code null} when none does. */
47	    private static String byPostcode(String postcode) {
48	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
49	            return null;
50	        }
51	        int value = Integer.parseInt(postcode);
52	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
53	            int[] range = entry.getValue();
54	            if (value >= range[0] && value <= range[1]) {
55	                return entry.getKey();
56	            }
57	        }
58	        return null;
59	    }
60	}
