16	    /** The maximum number of owners permitted in a single city. */
17	    private static final int CITY_CAPACITY = 50;
18	
19	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
20	            throws OwnerCityCapacityException {
21	        String city = request.getCity();
22	        int count = 0;
23	        for (Owner existing : ownerRepository.findAll()) {
24	            if (city == null ? existing.getCity() == null : city.equalsIgnoreCase(existing.getCity())) {
25	                count++;
26	            }
27	        }
28	        if (count >= CITY_CAPACITY) {
29	            throw new OwnerCityCapacityException(city, count);
30	        }
31	    }
