1	package org.springframework.samples.petclinic.model;
2	
3	/**
4	 * Derives an owner's numeric membership level, assigned once at creation.
5	 *
6	 * <p>Starts at {@code 1}; adds {@code 1} when an email address is present; adds {@code 1} when the
7	 * owner has no namesakes ({@code namesakeCount} is {@code 0}); the result is capped at {@code 3}.
8	 * Level {@code 4} is reserved for tenure and is never produced here.
9	 */
10	public final class MembershipLevel {
11	
12	    private MembershipLevel() {
13	    }
14	
15	    /** Compute the membership level (1..3) for the given owner. */
16	    public static int of(Owner owner) {
17	        int level = 1;
18	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
19	            level++;
20	        }
21	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
22	            level++;
23	        }
24	        return Math.min(level, 3);
25	    }
26	}
