3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.rest.escalation.OwnerPostcodeInvalidException;
6	
7	/**
8	 * Shared postcode handling for owner endpoints. An owner's postcode is optional; when supplied it
9	 * must be four digits and, when the city maps to a known region via the fixed city-to-region table
10	 * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}), it must fall within
11	 * that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
12	 * A city with no known region accepts any 4-digit postcode. The value is stored and returned as
13	 * given.
14	 */
15	final class OwnerPostcode {
16	
17	    /** City -&gt; canonical region. Anything not listed has no known region (any 4-digit is accepted). */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
20	
21	    /** Region -&gt; inclusive 4-digit postcode range {@code {low, high}}. */
22	    private static final Map<String, int[]> REGION_RANGE = Map.of(
23	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
24	
25	    private OwnerPostcode() {
26	    }
27	
28	    /**
29	     * Validates the supplied postcode for the given city. A null or blank postcode is accepted
30	     * (the field is optional). A non-blank postcode must be exactly four digits and, when the city
31	     * has a known region, must fall within that region's range.
32	     *
33	     * @throws OwnerPostcodeInvalidException when a supplied postcode is malformed or out of range.
34	     */
35	    static void validate(String postcode, String city) throws OwnerPostcodeInvalidException {
36	        if (postcode == null || postcode.isBlank()) {
37	            return;
38	        }
39	        if (!postcode.matches("[0-9]{4}")) {
40	            throw new OwnerPostcodeInvalidException(postcode);
41	        }
42	        String region = city == null ? null : CITY_REGION.get(city);
43	        int[] range = region == null ? null : REGION_RANGE.get(region);
44	        if (range != null) {
45	            int value = Integer.parseInt(postcode);
46	            if (value < range[0] || value > range[1]) {
47	                throw new OwnerPostcodeInvalidException(postcode);
48	            }
49	        }
50	    }
51	}
