1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.util.ArrayList;
6	import java.util.List;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	import org.springframework.samples.petclinic.repository.OwnerRepository;
11	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
12	
13	/**
14	 * Assigns a shared {@code householdId} when a create request opts in with
15	 * {@code sharesHousehold: true} and an existing owner already shares the household — the same
16	 * lastName (compared case-insensitively with collapsed whitespace) and the same address, compared
17	 * in normalized form (see {@link OwnerAddress#normalize(String)}). Duplicate detection is handled
18	 * separately by {@link CheckOwnerIdentityUnique}: household members with different telephones have
19	 * different identityKeys and are all allowed.
20	 *
21	 * <p>The identifier is a <em>stable</em> value derived deterministically from the normalized
22	 * lastName and address, so every owner in the same household receives the same id regardless of
23	 * creation order. Both the joining owner and every existing household member are updated to carry
24	 * it, so the household is linked from either side.
25	 *
26	 * <p>Runs after {@link BuildOwner} (the entity exists) and before {@link SaveOwner}, under the
27	 * request transaction so the updates to existing owners commit together with the new owner. When
28	 * the request does not opt in, or no existing household member is found, no id is assigned.
29	 */
30	public class AssignHousehold {
31	
32	    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository) {
33	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            return;
35	        }
36	        String lastName = normalize(owner.getLastName());
37	        String address = OwnerAddress.forComparison(owner.getAddress());
38	        List<Owner> household = new ArrayList<>();
39	        for (Owner existing : ownerRepository.findAll()) {
40	            if (lastName.equals(normalize(existing.getLastName()))
41	                    && address.equals(OwnerAddress.forComparison(existing.getAddress()))) {
42	                household.add(existing);
43	            }
44	        }
45	        if (household.isEmpty()) {
46	            return;
47	        }
48	        String householdId = deriveHouseholdId(lastName, address);
49	        owner.setHouseholdId(householdId);
50	        for (Owner existing : household) {
51	            if (!householdId.equals(existing.getHouseholdId())) {
52	                existing.setHouseholdId(householdId);
53	                ownerRepository.save(existing);
54	            }
55	        }
56	    }
57	
58	    /** Lower-cased, trimmed, with internal whitespace runs collapsed to a single space. */
59	    private static String normalize(String value) {
60	        if (value == null) {
61	            return "";
62	        }
63	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
64	    }
65	
66	    /** {@code HH-} followed by the first 12 upper-case hex characters of SHA-256(lastName|address),
67	     *  computed over the already-normalized values so it is identical for every household member. */
68	    private static String deriveHouseholdId(String normalizedLastName, String normalizedAddress) {
69	        try {
70	            byte[] digest = MessageDigest.getInstance("SHA-256")
71	                    .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
72	            StringBuilder sb = new StringBuilder();
73	            for (int i = 0; i < 6; i++) {
74	                sb.append(String.format("%02X", digest[i]));
75	            }
76	            return "HH-" + sb;
77	        }
78	        catch (Exception ex) {
79	            throw new IllegalStateException("SHA-256 unavailable", ex);
80	        }
81	    }
82	}
