3	import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;
4	
5	/**
6	 * Shared telephone handling for owner endpoints. A telephone is stored and returned in E.164 form:
7	 * keep a leading {@code '+'} and country code when the input supplies one, otherwise assume country
8	 * code {@code +61} and drop a single leading {@code '0'} from the national digits. Spaces, dashes and
9	 * brackets are stripped; the result must carry 8 to 15 digits after the {@code '+'}. So
10	 * {@code '0412 345 678'} becomes {@code '+61412345678'}. The national-number length must also match
11	 * the country code: {@code '+61'} requires 9 national digits and {@code '+1'} requires 10.
12	 */
13	final class OwnerTelephone {
14	
15	    private static final String DEFAULT_COUNTRY_CODE = "61";
16	
17	    private OwnerTelephone() {
18	    }
19	
20	    /**
21	     * Convert a raw telephone into its E.164 representation.
22	     *
23	     * @throws OwnerTelephoneInvalidException when the input cannot form a valid E.164 number.
24	     */
25	    static String toE164(String raw) throws OwnerTelephoneInvalidException {
26	        if (raw == null) {
27	            throw new OwnerTelephoneInvalidException(raw);
28	        }
29	        String trimmed = raw.trim();
30	        boolean hasPlus = trimmed.startsWith("+");
31	        String rest = hasPlus ? trimmed.substring(1) : trimmed;
32	        // Strip spaces, dashes and brackets; anything else left over is not a valid number.
33	        String cleaned = rest.replaceAll("[\\s()\\-]", "");
34	        if (cleaned.isEmpty() || !cleaned.matches("[0-9]+")) {
35	            throw new OwnerTelephoneInvalidException(raw);
36	        }
37	        String digits;
38	        if (hasPlus) {
39	            digits = cleaned;
40	        }
41	        else {
42	            // Assume the default country code, dropping a single leading '0' from the national digits.
43	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
44	            digits = DEFAULT_COUNTRY_CODE + national;
45	        }
46	        if (digits.length() < 8 || digits.length() > 15) {
47	            throw new OwnerTelephoneInvalidException(raw);
48	        }
49	        // The national-number length must match the country code: '+61' expects 9 national digits,
50	        // '+1' expects 10. Check the longer prefix first so a '+61' number is not read as '+1'.
51	        if (digits.startsWith("61")) {
52	            if (digits.length() - 2 != 9) {
53	                throw new OwnerTelephoneInvalidException(raw);
54	            }
55	        }
56	        else if (digits.startsWith("1")) {
57	            if (digits.length() - 1 != 10) {
58	                throw new OwnerTelephoneInvalidException(raw);
59	            }
60	        }
61	        return "+" + digits;
62	    }
63	}
